**`ErrorBoundary.tsx`**

```tsx
import React, { Component, ErrorInfo, ReactNode } from "react";

interface Props {
  children: ReactNode;
  fallback?: ReactNode;
  onError?: (error: Error, errorInfo: ErrorInfo) => void;
}

interface State {
  hasError: boolean;
  error: Error | null;
  errorInfo: ErrorInfo | null;
}

export class ErrorBoundary extends Component<Props, State> {
  state: State = {
    hasError: false,
    error: null,
    errorInfo: null,
  };

  static getDerivedStateFromError(error: Error): Partial<State> {
    return { hasError: true, error };
  }

  componentDidCatch(error: Error, errorInfo: ErrorInfo): void {
    this.setState({ errorInfo });

    console.error("[ErrorBoundary] Caught render error:", error);
    console.error("[ErrorBoundary] Component stack:", errorInfo.componentStack);

    this.props.onError?.(error, errorInfo);
  }

  private handleRetry = (): void => {
    this.setState({ hasError: false, error: null, errorInfo: null });
  };

  render(): ReactNode {
    if (!this.state.hasError) {
      return this.props.children;
    }

    if (this.props.fallback) {
      return this.props.fallback;
    }

    return (
      <DefaultFallback
        error={this.state.error}
        errorInfo={this.state.errorInfo}
        onRetry={this.handleRetry}
      />
    );
  }
}

interface FallbackProps {
  error: Error | null;
  errorInfo: ErrorInfo | null;
  onRetry: () => void;
}

function DefaultFallback({ error, errorInfo, onRetry }: FallbackProps) {
  return (
    <div role="alert" style={styles.container}>
      <h2 style={styles.heading}>Something went wrong</h2>
      <p style={styles.message}>{error?.message ?? "An unexpected error occurred."}</p>
      {process.env.NODE_ENV !== "production" && errorInfo && (
        <details style={styles.details}>
          <summary style={styles.summary}>Stack trace</summary>
          <pre style={styles.pre}>
            {error?.stack}
            {"\n\nComponent stack:"}
            {errorInfo.componentStack}
          </pre>
        </details>
      )}
      <button onClick={onRetry} style={styles.button} type="button">
        Try again
      </button>
    </div>
  );
}

const styles: Record<string, React.CSSProperties> = {
  container: {
    padding: "2rem",
    maxWidth: "600px",
    margin: "2rem auto",
    border: "1px solid #f5c6cb",
    borderRadius: "8px",
    backgroundColor: "#fff5f5",
    fontFamily: "sans-serif",
  },
  heading: {
    margin: "0 0 0.5rem",
    color: "#c0392b",
    fontSize: "1.25rem",
  },
  message: {
    margin: "0 0 1rem",
    color: "#333",
  },
  details: {
    margin: "0 0 1rem",
  },
  summary: {
    cursor: "pointer",
    color: "#555",
    fontSize: "0.875rem",
  },
  pre: {
    marginTop: "0.5rem",
    padding: "0.75rem",
    backgroundColor: "#f8f8f8",
    borderRadius: "4px",
    fontSize: "0.75rem",
    overflowX: "auto",
    whiteSpace: "pre-wrap",
    wordBreak: "break-word",
  },
  button: {
    padding: "0.5rem 1.25rem",
    backgroundColor: "#c0392b",
    color: "#fff",
    border: "none",
    borderRadius: "4px",
    cursor: "pointer",
    fontSize: "0.875rem",
  },
};
```

