**`ErrorBoundary.test.tsx`**

```tsx
import React from "react";
import { render, screen, fireEvent } from "@testing-library/react";
import { ErrorBoundary } from "./ErrorBoundary";

function Bomb({ shouldThrow }: { shouldThrow: boolean }) {
  if (shouldThrow) throw new Error("Test explosion");
  return <div>OK</div>;
}

// Silence console.error in tests
beforeEach(() => jest.spyOn(console, "error").mockImplementation(() => {}));
afterEach(() => jest.restoreAllMocks());

test("renders children when there is no error", () => {
  render(
    <ErrorBoundary>
      <Bomb shouldThrow={false} />
    </ErrorBoundary>
  );
  expect(screen.getByText("OK")).toBeInTheDocument();
});

test("renders fallback UI when a child throws", () => {
  render(
    <ErrorBoundary>
      <Bomb shouldThrow />
    </ErrorBoundary>
  );
  expect(screen.getByRole("alert")).toBeInTheDocument();
  expect(screen.getByText("Test explosion")).toBeInTheDocument();
});

test("retry button resets the error boundary", () => {
  const { rerender } = render(
    <ErrorBoundary>
      <Bomb shouldThrow />
    </ErrorBoundary>
  );
  fireEvent.click(screen.getByRole("button", { name: /try again/i }));
  rerender(
    <ErrorBoundary>
      <Bomb shouldThrow={false} />
    </ErrorBoundary>
  );
  expect(screen.getByText("OK")).toBeInTheDocument();
});

test("calls onError prop with error details", () => {
  const onError = jest.fn();
  render(
    <ErrorBoundary onError={onError}>
      <Bomb shouldThrow />
    </ErrorBoundary>
  );
  expect(onError).toHaveBeenCalledWith(
    expect.objectContaining({ message: "Test explosion" }),
    expect.objectContaining({ componentStack: expect.any(String) })
  );
});

test("renders custom fallback when provided", () => {
  render(
    <ErrorBoundary fallback={<div>Custom fallback</div>}>
      <Bomb shouldThrow />
    </ErrorBoundary>
  );
  expect(screen.getByText("Custom fallback")).toBeInTheDocument();
});
```

---

**Usage**

```tsx
// Wrap any subtree — errors won't bubble past the boundary
<ErrorBoundary onError={(err, info) => myLogger.capture(err, info)}>
  <MyFeature />
</ErrorBoundary>

// Custom fallback per boundary
<ErrorBoundary fallback={<p>Widget failed to load.</p>}>
  <DataWidget />
</ErrorBoundary>
```

---

Key design decisions:

- **`getDerivedStateFromError`** flips the error flag synchronously so React renders the fallback on the same pass, avoiding a blank frame.
- **`componentDidCatch`** is where side-effects (logging) go — it's called after the fallback is painted.
- The stack trace block is gated on `NODE_ENV !== 'production'` so it never leaks internals to users.
- The `onError` prop lets callers plug in Sentry, Datadog, or any error reporting service without coupling the boundary to a specific SDK.
- Retry resets all three pieces of state together so a stale `errorInfo` can't linger.
